        "c11a799b86594182b747ec8d0974ff70": {
          "id": "c11a799b86594182b747ec8d0974ff70",
          "name": "Get User Location & Location Config",
          "script": "(function execute() {\n\n    //TODO: in all flows convert inputs to lower case. \n    if(null!= vaInputs.badge_type &&  \"\"!= vaInputs.badge_type){\n        vaVars.badge_type= vaInputs.badge_type;\n    }else{\n        vaInputs.badge_type = \"\";\n        vaVars.badge_type= \"\";\n    }\n\n    var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')\n    idenlocationGr.addQuery('identity',vaInputs.user_sys_id);\n    idenlocationGr.query();\n    var location = \"\";\n    if(idenlocationGr.next()){\n        location = idenlocationGr.location;\n        vaVars.user_location = location;\n    }\n     //TODO : will use guardian Location administrator config.\n    var dtInputs = {};\n    dtInputs.user_location = vaVars.user_location;\n    var result = new GuardianAIAgentHelper().getDTConfigs(\"a57ddb4833083650bf1221382e5c7b7e\",dtInputs);\n    gs.info(\"DT Result Mob Cred : \"+JSON.stringify(result));\n    vaVars.location_mobile_cred_enabled = result.MC_SUPPORT;\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
        "4714693e19b843dfa3edff4a07f9f956": {
          "id": "4714693e19b843dfa3edff4a07f9f956",
          "name": "get DT Badge Config",
          "script": "(function execute() {\n    var badge_type_calculated = \"\";\n    // DON'T CHANGE CODE UNLESS WILLING TO TEST 16 scenarios ::BEGIN.\n    var badge_issue_userInput = vaInputs.badge_issue_type;\n    if(null == badge_issue_userInput || undefined == badge_issue_userInput){\n         badge_issue_userInput= \"\";\n    }else{\n          badge_issue_userInput = badge_issue_userInput.toString();\n    }\n    if(null != badge_issue_userInput && \"\" != badge_issue_userInput && badge_issue_userInput.indexOf(\"plastic\") > -1){\n        if(null != vaInputs.badge_type_input_choice && \"\" != vaInputs.badge_type_input_choice ){\n            badge_type_calculated = vaInputs.badge_type_input_choice.toString();\n        } else {\n            badge_type_calculated = vaVars.badge_type.toString();\n        }\n    } else if(null != badge_issue_userInput && \"\" != badge_issue_userInput && badge_issue_userInput.indexOf(\"mobile\") > -1){\n        badge_type_calculated = \"mobile credentials\";\n    } else {\n        if(vaVars.badge_type != \"\"){\n            badge_type_calculated = vaVars.badge_type;\n        }else{\n            badge_type_calculated = vaInputs.badge_type_input_choice;\n        }\n    }\n    vaVars.badge_type = badge_type_calculated;\n    gs.info(\"FINAL BADGE_TYPE  ====>\" + badge_type_calculated);\n   \n  \n    var inputs = {};\n    inputs['user_location'] = vaVars.user_location; // Reference, Sys ID of the record \n    inputs['user_type'] = vaInputs.user_type_sys_id; // Reference, Sys ID of the record \n    inputs['u_badge_type'] = vaVars.badge_type; // String \n    inputs['u_badge_action'] = \"assign\"; // String \n    \n    var dt = new sn_dt.DecisionTableAPI();\n    var response = dt.getDecision('0d37c78833843650bf1221382e5c7bc7', inputs);\n\n    var result_elements = response.result_elements;\n    vaVars.dt_res_u_auto_badge_allocation = result_elements.u_auto_badge_allocation.getValue(); // True/False\n    vaVars.dt_res_u_create_request = result_elements.u_create_request.getValue(); // True/False\n    vaVars.dt_res_u_def_valid_from = result_elements.u_def_valid_from.getValue(); // True/False\n    vaVars.dt_res_u_def_valid_to = result_elements.u_def_valid_to.getValue(); // Duration\n    vaVars.dt_res_u_def_access = result_elements.u_def_access.getValue(); // True/False\n   \n    //default system\n    var locationAdminGr = new GlideRecordSecure('x_aleen_snguardian_badge_office');\n    locationAdminGr.addQuery('locationsLIKE'+vaVars.user_location);\n    locationAdminGr.orderBy('order');\n    locationAdminGr.query();\n    if(locationAdminGr.next()){\n        vaVars.default_system = locationAdminGr.system;\n    }\n\n    gs.info(\"Response ValFr : \"+vaVars.dt_res_u_def_valid_from);\n    gs.info(\"Response ValTo : \"+vaVars.dt_res_u_def_valid_to);\n    gs.info(\"Response Badge : \"+vaVars.dt_res_u_auto_badge_allocation);\n\n    //TODO :  if  vaVars.dt_res_u_auto_badge_allocation == 1\n    //get a badge Id and set Value to =    vaInputs.select_badge_number = \"1234\"\n    if(!vaVars.dt_res_u_auto_badge_allocation){\n        // vaVars.\n    }\n\n\n    //TODO :  if  vaVars.dt_res_u_def_valid_from == 0\n    //set cuurent date   Value to =    vaInputs.badge_valid_from \n    if(!vaVars.dt_res_u_def_valid_from || vaVars.dt_res_u_def_valid_from==\"false\"){ //false\n        vaVars.dt_res_u_def_valid_from = 0;\n    }else{\n        vaVars.dt_res_u_def_valid_from = 1;\n        //user preference current time - location current time ?\n        vaVars.valid_from = new GlideDateTime().getDisplayValue();\n    }\n\n\n    //TODO :  if  vaVars.dt_res_u_def_valid_to == 0\n    //calc Value to =    vaInputs.badge_valid_to\n    if(!vaVars.dt_res_u_def_valid_to || \"\"==vaVars.dt_res_u_def_valid_to){\n        vaVars.dt_res_u_def_valid_to = 0;\n    }else{\n        vaVars.dt_res_u_def_valid_to = 1;\n    }\n\n    //Pass  dt_res_u_def_access to SUBFLOW\n\n\n\n    \n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
